const item = $input.first();
let data = item.json;

// Unwrap common AI Agent output envelopes.
if (data && typeof data === 'object' && data.output !== undefined) data = data.output;

function extractJsonText(value) {
  let text = String(value ?? '').replace(/^\uFEFF/, '').trim();
  if (!text) throw new Error('AI returned an empty response.');
  const fenced = text.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fenced) text = fenced[1].trim();
  if (!text.startsWith('{')) {
    const start = text.indexOf('{');
    if (start < 0) throw new Error('No JSON object was found in the AI response.');
    let depth = 0, inString = false, escaped = false, end = -1;
    for (let i = start; i < text.length; i++) {
      const ch = text[i];
      if (inString) {
        if (escaped) escaped = false;
        else if (ch === '\\') escaped = true;
        else if (ch === '"') inString = false;
      } else {
        if (ch === '"') inString = true;
        else if (ch === '{') depth++;
        else if (ch === '}') {
          depth--;
          if (depth === 0) { end = i + 1; break; }
        }
      }
    }
    if (end < 0) throw new Error('The AI response contains an incomplete JSON object.');
    text = text.slice(start, end);
  }
  return text;
}

if (typeof data === 'string') {
  try { data = JSON.parse(extractJsonText(data)); }
  catch (e) {
    return [{json:{valid:false,errors:['AI output could not be parsed as JSON: ' + String(e)],html:'',title:'',requirements:[],implementationSummary:''}}];
  }
}
if (data && typeof data === 'object' && data.output !== undefined) {
  let nested = data.output;
  if (typeof nested === 'string') {
    try { nested = JSON.parse(extractJsonText(nested)); }
    catch (e) {
      return [{json:{valid:false,errors:['Nested AI output could not be parsed: ' + String(e)],html:'',title:'',requirements:[],implementationSummary:''}}];
    }
  }
  data = nested;
}

const errors = [];
let html = data && typeof data.html === 'string' ? data.html.replace(/^\uFEFF/, '').trim() : '';
const title = data && typeof data.title === 'string' ? data.title.trim() : '';
const requirements = Array.isArray(data && data.requirements) ? data.requirements : [];
const implementationSummary = data && typeof data.implementationSummary === 'string' ? data.implementationSummary : '';

if (!html) errors.push('The generated HTML is missing or empty.');
if (html.length > 2_000_000) errors.push('The generated HTML exceeds the 2 MB size limit.');
if (/^```/.test(html) || /```$/.test(html)) errors.push('The HTML must not contain Markdown code fences.');
if (!/^<!doctype html>/i.test(html)) errors.push('The document must begin with <!DOCTYPE html>.');
for (const [tag, pattern] of [
  ['html', /<html\b/i], ['head', /<head\b/i], ['body', /<body\b/i],
  ['closing html', /<\/html\s*>/i], ['closing head', /<\/head\s*>/i], ['closing body', /<\/body\s*>/i],
  ['title', /<title\b[\s\S]*?<\/title>/i], ['embedded CSS', /<style\b[\s\S]*?<\/style>/i],
  ['viewport metadata', /<meta\b[^>]*name\s*=\s*["']viewport["']/i]
]) {
  if (!pattern.test(html)) errors.push(`Required HTML element or feature is missing: ${tag}.`);
}
if (!title) errors.push('Website title is missing.');
if (requirements.length === 0) errors.push('The AI did not return a non-empty requirements list.');
else {
  for (const [i, req] of requirements.entries()) {
    if (!req || typeof req !== 'object' || !req.id || !req.description ||
        !Array.isArray(req.implementedIn) || req.implementedIn.length === 0) {
      errors.push(`Requirement ${i + 1} is missing id, description, or implementedIn.`);
    }
  }
}
if (!implementationSummary.trim()) errors.push('Implementation summary is missing.');

return [{json:{
  valid: errors.length === 0,
  errors,
  html,
  title,
  requirements,
  implementationSummary
}}];

const item = $input.first();
const html = item.json.html;
if (typeof html !== 'string' || !html.trim()) {
  throw new Error('Cannot create a download: validated HTML is missing.');
}

const rawTitle = String(item.json.title || 'kontrolled-website');
const slug = rawTitle
  .toLowerCase()
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 60) || 'kontrolled-website';
const fileName = `${slug}.html`;

const binary = await this.helpers.prepareBinaryData(
  Buffer.from(html, 'utf8'),
  fileName,
  'text/html'
);

return [{
  json: {
    success: true,
    title: rawTitle,
    fileName,
    implementationSummary: item.json.implementationSummary,
    requirements: item.json.requirements
  },
  binary: { data: binary }
}];
